#include "ark/occt_solid.hpp"
#include "ark/agent.hpp"
#include "../src/occt/common.hpp"
#include <BRepCheck_Analyzer.hxx>
#include <BRepClass3d_SolidClassifier.hxx>
#include <BRepPrimAPI_MakeBox.hxx>
#include <cmath>
#include <iostream>
#include <stdexcept>
using namespace ark::occt;
namespace {
void check(bool b,const char* message){if(!b)throw std::runtime_error(message);}
V json(const char* source){V out;check(arkjson::parse(source,out),"test JSON");return out;}
V accepted(const V& response){if(response.find("isError")->b)throw std::runtime_error(response.find("structuredContent")->dump());return *response.find("structuredContent");}
bool rejects(const V& request){try{modelSolidNative(request);return false;}catch(const std::exception&){return true;}}
V box(){return modelSolidNative(json(R"({"op":"box","width":10,"depth":20,"height":30})"));}
V pull(const V& source,const V& vertex,double dx,double dy,double dz){V q=V::makeObj();q.set("op",V::makeStr("vertex_pull"));q.set("input_brep",*source.find("brep_base64"));q.set("input_topology",*source.find("topology"));q.set("source_topology",*vertex.find("source_topology"));q.set("source_vertex",*vertex.find("name"));q.set("dx",V::makeNum(dx));q.set("dy",V::makeNum(dy));q.set("dz",V::makeNum(dz));return q;}
const V& corner(const V& source,double x,double y,double z){for(auto& vertex:source.find("topology")->find("vertices")->arr){const auto& p=vertex.find("point_mm")->arr;if(std::abs(p[0].num-x)<1e-8&&std::abs(p[1].num-y)<1e-8&&std::abs(p[2].num-z)<1e-8)return vertex;}throw std::runtime_error("missing exact test vertex");}
void geometry(){
    const auto source=box();const auto saved=source.dump();check(source.find("topology")->find("vertices")->arr.size()==8&&source.find("topology")->find("vertex_inventory_complete")->b,"box publishes eight unique exact vertices");
    for(auto& vertex:source.find("topology")->find("vertices")->arr){const auto& point=vertex.find("point_mm")->arr;const double sx=point[0].num>0?1:-1,sy=point[1].num>0?1:-1,sz=point[2].num>0?1:-1;const auto result=modelSolidNative(pull(source,vertex,.5*sx,.6*sy,.7*sz));
        const auto& report=*result.find("report"),recipe=*report.find("vertex_pull");check(report.find("brep_valid")->b&&report.find("solids")->num==1,"pull produces one valid exact solid");check(report.find("self_intersections_checked")->b&&recipe.find("self_intersections_checked")->b,"pull checks exact self interference");check(recipe.find("split_quad_count")->num==3&&report.find("faces")->num==9,"three incident quads become six exact facets");check(std::abs(report.find("volume_mm3")->num-(6000+(600*.5+300*.6+200*.7)/6))<1e-5,"moved corner volume matches independent wedge integral");check(source.dump()==saved,"pull does not mutate input source package");
        bool found=false;for(auto& current:result.find("topology")->find("vertices")->arr){const auto& p=current.find("point_mm")->arr;if(std::abs(p[0].num-point[0].num-.5*sx)<1e-8&&std::abs(p[1].num-point[1].num-.6*sy)<1e-8&&std::abs(p[2].num-point[2].num-.7*sz)<1e-8)found=true;check(current.find("source_topology")->str==result.find("topology")->find("brep_sha256")->str,"output vertices bind the new exact B-rep hash");}check(found,"moved exact vertex survives in output inventory");
        const auto shape=readBrep(result.find("brep_base64")->str);check(BRepCheck_Analyzer(shape).IsValid(),"sewn B-rep independent validity");
    }
    const auto result=modelSolidNative(pull(source,corner(source,10,20,30),1,2,3));std::cout<<"vertex reference evidence\n";int split=0,deleted=0;for(auto& reference:result.find("topology")->find("references")->arr){if(reference.find("name")->str.find("@ark.")!=std::string::npos)continue;if(reference.find("kind")->str=="face"&&reference.find("status")->str=="split"){++split;check(reference.find("split_into")&&reference.find("split_into")->arr.size()==2,"split face exposes exact replacements");}if(reference.find("kind")->str=="edge"&&reference.find("status")->str=="deleted")++deleted;}
    check(split==3&&deleted==3,"incident faces split and incident source edges delete explicitly");
    const auto chained=modelSolidNative(pull(result,corner(result,11,22,33),.2,.3,.4));check(chained.find("report")->find("solids")->num==1&&chained.find("report")->find("self_intersections_checked")->b,"pulled faceted source supports another exact vertex pull");check(chained.find("report")->find("vertex_pull")->find("split_quad_count")->num==0,"existing exact triangular facets stay explicit during subsequent pull");
    const auto other=modelSolidNative(pull(result,corner(result,0,0,0),-.2,-.3,-.4));check(other.find("report")->find("solids")->num==1,"another exact source corner can be pulled downstream");
    std::cout<<"vertex frame\n";V frame=V::makeObj();frame.set("input_brep",*result.find("brep_base64"));frame.set("topology",*result.find("topology"));frame.set("reference",V::makeStr("x_min"));check(referenceFrameNative(frame).find("frame")!=nullptr,"unaffected semantic face remains bound");
    std::cout<<"vertex STEP\n";auto file=fs::temp_directory_path()/"ark-native-vertex-pull.step";writeStep(readBrep(result.find("brep_base64")->str),file);check(symmetricDifference(readBrep(result.find("brep_base64")->str),readStep(file))<1e-5,"faceted exact STEP roundtrip");fs::remove(file);
    auto invalid=pull(source,corner(source,10,20,30),1,2,3);invalid.set("source_topology",V::makeStr(std::string(64,'0')));check(rejects(invalid),"stale exact topology cannot retarget vertex");invalid=pull(source,corner(source,10,20,30),-10,0,0);check(rejects(invalid),"collapsed source edge rejects");invalid=pull(source,corner(source,10,20,30),-30,-40,-50);check(rejects(invalid),"crossed or inverted geometry rejects");invalid=pull(source,corner(source,10,20,30),0,0,0);check(rejects(invalid),"zero displacement rejects");
    auto cylinder=modelSolidNative(json(R"({"op":"cylinder","radius":10,"height":30})"));check(rejects(pull(cylinder,cylinder.find("topology")->find("vertices")->arr.front(),1,0,0)),"curved source cannot fall back to display mesh");
    V cut=V::makeObj();cut.set("op",V::makeStr("cut"));cut.set("input_brep",*source.find("brep_base64"));cut.set("input_topology",*source.find("topology"));cut.set("tool_brep",V::makeStr(brepData(BRepPrimAPI_MakeBox(gp_Pnt(3,4,-1),4,6,32).Shape())));const auto holed=modelSolidNative(cut);check(rejects(pull(holed,corner(holed,10,20,30),1,0,0)),"holed planar face explicitly rejects");
}
void persistence(){
    ark::AgentSession session;accepted(session.call("doc_apply",json(R"({"expected_revision":0,"commands":[{"op":"feature.add","type":"native_solid","name":"Box","native":{"op":"box"},"p":{"width":10,"depth":20,"height":30}}]})")));const auto source=session.document.evalBodies.front().nativeData;const auto& selected=corner(source,10,20,30);const auto sourceIntent=session.document.features.front().nativeSpec.dump();V spec=V::makeObj();spec.set("op",V::makeStr("vertex_pull"));spec.set("source_vertex",*selected.find("name"));spec.set("source_topology",*selected.find("source_topology"));
    V command=V::makeObj();command.set("op",V::makeStr("feature.add"));command.set("type",V::makeStr("native_solid"));command.set("name",V::makeStr("Pulled corner"));command.set("native",spec);V inputs=V::makeArr();inputs.arr.push_back(V::makeNum(1));command.set("inputs",inputs);command.set("p",json(R"({"dx":1,"dy":2,"dz":3})"));V commands=V::makeArr();commands.arr.push_back(command);V args=V::makeObj();args.set("expected_revision",V::makeNum(session.revision));args.set("commands",commands);accepted(session.call("doc_apply",args));
    check(session.document.features.front().nativeSpec.dump()==sourceIntent,"authoring adds downstream recipe and preserves original source");const auto saved=ark::documentToJson(session.document),authored=ark::documentToJson(session.document,true,false);V serialized;check(arkjson::parse(authored,serialized)&&serialized.find("version")->num==37,"vertex recipe requires source format 37");ark::Document restored;std::string error;check(ark::documentFromJson(saved,restored,&error),"vertex recipe loads");restored.recompute();check(restored.evalBodies.back().nativeData.find("report")->find("vertex_pull"),"vertex source reevaluates after reload");
    const auto revision=session.revision;auto upstream=json(R"({"commands":[{"op":"feature.edit","id":1,"p":{"width":12}}]})");upstream.set("expected_revision",V::makeNum(revision));check(session.call("doc_apply",upstream).find("isError")->b&&session.revision==revision&&ark::documentToJson(session.document)==saved,"changed exact source digest cannot silently retarget a vertex");
    auto old=serialized;old.set("version",V::makeNum(36));ark::Document legacy;check(!ark::documentFromJson(old.dump(),legacy,&error),"old document version cannot hide a vertex recipe");
    auto edit=json(R"({"expected_revision":0,"commands":[{"op":"feature.edit","id":2,"p":{"dx":2}}]})");check(session.call("doc_apply",edit).find("isError")->b&&session.revision==revision,"vertex stale edit rejects atomically");edit.set("expected_revision",V::makeNum(revision));auto rows=*edit.find("commands");rows.arr[0].set("p",json(R"({"dx":-10,"dy":0,"dz":0})"));edit.set("commands",rows);check(session.call("doc_apply",edit).find("isError")->b&&session.revision==revision&&ark::documentToJson(session.document)==saved,"invalid pull rollback preserves exact source and revision");rows.arr[0].set("p",json(R"({"dx":2,"dy":3,"dz":4})"));edit.set("commands",rows);accepted(session.call("doc_apply",edit));accepted(session.call("doc_undo",V::makeObj()));check(ark::documentToJson(session.document,true,false)==authored,"vertex source undo restores recipe");
}
}
int main(){std::cout<<std::unitbuf;try{std::cout<<"vertex geometry\n";geometry();std::cout<<"vertex source\n";persistence();std::cout<<"native exact vertex pull tests passed\n";}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
